entries[53] = { ["name"] = "Meucheln", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nMeuchelt das Ziel und fügt ihm so 380% Waffenschaden plus 459 zu. Muss hinter dem Ziel sein. In der Waffenhand muss sich ein Dolch befinden. Gewährt 1 Combopunkt." }
