entries[66] = { ["name"] = "Unsichtbarkeit", ["text"] = "3% von Grundmana\nSofort 5 min Abklingzeit\nLässt den Zaubernden im Verlauf von 3 Sek. bis zur Unsichtbarkeit verblassen und verringert mit jeder Sekunde die Bedrohung. Während Ihr unsichtbar seid, könnt Ihr von Gegnern nicht als Ziel gewählt werden. Hält 20 Sek. lang an. [ Glyphe 'Unsichtbarkeit' : Während Ihr unsichtbar seid, ist Euer Bewegungstempo um 40% erhöht ]\nDer Effekt wird abgebrochen, wenn Ihr Aktionen ausführt." }
entries[71] = { ["name"] = "Verteidigungshaltung", ["text"] = "Sofort 1.5 sek. Abklingzeit\nEine defensive Kampfhaltung.\n\nVerringert den erlittenen Schaden um 25%.\nErhöht außerdem die erzeugte Bedrohung deutlich.\nErzeugt im Kampf alle 3 Sek. 1 Wut." }
entries[75] = { ["name"] = "Automatischer Schuss", ["text"] = "40 Meter Reichweite\nSofort\nBenötigt Distanzwaffe\nSchießt automatisch auf das Ziel, bis die Aktion abgebrochen wird." }
