entries[78] = { ["name"] = "Heldenhafter Stoß", ["text"] = "30 Wut Nahkampfreichweite\nSpontanzauber 1.5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin Angriff, der sofort 110% Waffenschaden plus 499 verursacht [154% plus ( 499 * 1.40) wenn eine Einhandwaffe angelegt ist] [ Glyphe 'Verwehrende Stöße' : Zusätzlich wird das Bewegungstempo des Ziels 8 Sek. lang um 50% verringert ].\n\nSetzt diese Fähigkeit ein, wenn Ihr überschüssige Wut zur Verfügung habt." }
entries[81] = { ["name"] = "Ausweichen", ["text"] = "Gewährt die Chance, Nahkampfattacken des Feindes auszuweichen." }
entries[87] = { ["name"] = "Automatische Immunität", ["text"] = "Sofort\nMacht Euch gegen alle Zaubermechanismen immun. Wird in automatischen Skripten verwendet, um Bots gegen negative Effekte immun zu machen, wobei diese weiterhin mit Objekten interagieren können." }
entries[89] = { ["name"] = "Verkrüppeln", ["text"] = "30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nVerkrüppelt das Ziel, verringert dessen Bewegungstempo um 40 % und erhöht die Zeit zwischen Nahkampf- und Distanzangriffen um 26 %. Hält 20 Sek. lang an." }
entries[91] = { ["name"] = "Wilder Sturmangriff", ["text"] = "Nächster Nahkampf" }
entries[96] = { ["name"] = "Zerstückeln", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nErhöht den Schaden Eures nächsten Nahkampfangriffes um 100 und lässt das Ziel bluten." }
entries[99] = { ["name"] = "Desorientierendes Gebrüll", ["text"] = "Sofort 30 sek. Abklingzeit\nRuft den Geist Ursols an, dessen Brüllen alle Gegner innerhalb von 10 Metern 3 Sek. lang desorientiert. Jeglicher zugefügter Schaden wird den Effekt abbrechen. In allen Gestalten einsetzbar." }
entries[100] = { ["name"] = "Sturmangriff", ["text"] = "8 - 25 Meter Reichweite\nSofort 20 sek. Abklingzeit\nFuror ( Hotfix - Passivfähigkeit )\nStürmt auf einen Gegner zu und betäubt ihn . Hält 1.50 Sek. lang an . Erzeugt 20 Wut.\n\nWaffen, Schutz\nStürmt auf einen Gegner zu und [ Kriegstreiber : macht ihn bewegungsunfähig / betäubt ihn]. [ Glyphe 'Blitz' : Wirkt sich außerdem auf 2 weitere Ziele in der Nähe aus ] Hält [ Kriegstreiber : 4 Sek. lang an und verringert das Bewegungstempo des Ziels 15 Sek. lang um 50% / 1.50 Sek. lang an]. Erzeugt 20 Wut." }
entries[101] = { ["name"] = "Straucheln", ["text"] = "15 Energie Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nBringt den humanoiden Feind zu Fall, wobei 10 Schaden verursacht werden und der Gegner 3 Sek. lang am Boden liegt. Gewährt 1 Combopunkt." }
entries[107] = { ["name"] = "Blocken", ["text"] = "Benötigt Schild\nGewährt die Chance, Nahkampfattacken und Distanzangriffe des Feindes zu blocken." }
