entries[113] = { ["name"] = "Eisketten", ["text"] = "20 Mana 30 Meter Reichweite\nWirken in 1.5 sek.\nSchlingt eisige Ketten um das Ziel, welche es 6 Sek. lang an Ort und Stelle festhalten." }
entries[116] = { ["name"] = "Frostblitz", ["text"] = "4% von Grundmana 40 Meter Reichweite\nWirken in 2 sek.\nSchleudert einen Frostblitz auf den Gegner, der 1 Frostschaden verursacht und sein Bewegungstempo 15 Sek. lang um 50% verringert." }
entries[118] = { ["name"] = "Verwandlung", ["text"] = "2% von Grundmana 30 Meter Reichweite\nWirken in 1.7 sek.\nVerwandelt den Gegner in [ Glyphe 'Pinguin' : einen harmlosen Pinguin ] [ Glyphe 'Affe' : einen harmlosen Affen ] [ Glyphe 'Stachelschwein' : ein harmloses Stachelschwein ] [ Glyphe 'Bärenjunges' : ein harmloses Eisbärenjunges / ein harmloses Schaf ] und zwingt ihn, 50 Sek. lang so herumzuwandern.\n\nWährend der Gegner in [ Glyphe 'Pinguin' : einen Pinguin ] [ Glyphe 'Affe' : einen Affen ] [ Glyphe 'Stachelschwein' : ein Stachelschwein ] [ Glyphe 'Bärenjunges' : ein Eisbärenjunges / ein Schaf ] verwandelt ist, kann er weder angreifen noch Zauber wirken, regeneriert sich aber sehr schnell. Jeglicher erlittene Schaden wandelt ihn in seine normale Gestalt zurück.\n\nEs kann immer nur jeweils ein Ziel verwandelt werden. Wirkt nur bei Wildtieren, Humanoiden und Tieren." }
entries[120] = { ["name"] = "Kältekegel", ["text"] = "4% von Grundmana\nSofort 10 sek. Abklingzeit\nFügt Zielen in einem kegelförmigen Bereich vor dem Zaubernden 1 Frostschaden zu und verlangsamt sie 6 Sek. lang um 60%." }
entries[122] = { ["name"] = "Frostnova", ["text"] = "2% von Grundmana\nSofort 25 sek. Abklingzeit\nFügt nahen Gegnern innerhalb von 12 Metern im Umkreis um den Zaubernden 552 Frostschaden zu und friert sie bis zu 8 Sek. lang fest. Erlittener Schaden kann den Effekt unterbrechen." }
entries[124] = { ["name"] = "Heilige Handgranate des Widerstands", ["text"] = "30 Meter Reichweite\nSofort 5 sek. Abklingzeit\nSegnet alle Ziele mit einer heiligen Machtinfusion oder verflucht sie mit dem Bann aller Schlachtzügler." }
entries[126] = { ["name"] = "Auge von Kilrogg", ["text"] = "4% von Grundmana Unbegrenzte Reichweite\nWirken in 2 sek.\nBeschwört das Auge von Kilrogg und bindet Eure Sicht daran. Das Auge [ Glyphe 'Auge von Kilrogg' : fliegt sehr schnell / ist verstohlen und bewegt sich schnell], ist jedoch sehr fragil. [ Glyphe 'Auge von Kilrogg' : Wenn Ihr 'Dämonischer Zirkel: Beschwören' wirkt, während Ihr ein Auge von Kilrogg kontrolliert, wird der Beschwörungszirkel an der Position des Auges erscheinen ]" }
entries[130] = { ["name"] = "Langsamer Fall", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nVerringert 30 Sek. lang das Falltempo eines verbündeten Gruppen- oder Schlachtzugsmitglieds." }
entries[133] = { ["name"] = "Feuerball", ["text"] = "4% von Grundmana 40 Meter Reichweite\nWirken in 2.25 sek.\nSchleudert eine glühende Kugel, die 1561 Feuerschaden verursacht." }
