entries[324] = { ["name"] = "Blitzschlagschild", ["text"] = "Sofort\nDer Zaubernde wird von einer reaktiven Blitzbarriere umgeben. Wenn der Zaubernde von einem Nahkampf-, Distanz- oder Zauberangriff getroffen wird, erleidet der Angreifer 630 Naturschaden. Dieser Effekt kann nur einmal alle paar Sekunden ausgelöst werden. Hält 1 Stunde lang an.\n\nEs kann immer nur einer Eurer Elementarschilde gleichzeitig auf Euch aktiv sein.\n(1.5s Abklingzeit)" }
