entries[355] = { ["name"] = "Spott", ["text"] = "30 Meter Reichweite\nSofort 8 sek. Abklingzeit\nVerspottet das Ziel, damit es Euch angreift, und erhöht die von Euch gegen das Ziel erzeugte Bedrohung für 3 Sek. um 200%." }
