entries[379] = { ["name"] = "Erdschild", ["text"] = "Unbegrenzte Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild, der eine Chance gewährt, Zauberunterbrechungen durch Schaden zu vermeiden. Angriffe heilen das geschützte Ziel, dieser Effekt kann jedoch nur einmal innerhalb einiger Sekunden ausgelöst werden. Begrenzte Aufladungen. Dieser Schild kann immer nur auf einem Ziel gleichzeitig aktiv sein, und auf jedem Ziel kann nur ein Elementarschild aktiv sein." }
