entries[546] = { ["name"] = "Wasserwandeln", ["text"] = "3.5% von Grundmana 30 Meter Reichweite\nSofort\nErmöglicht dem befreundeten Ziel, 10 Min. lang auf Wasser zu wandern. Jeglicher erlittene Schaden hebt den Effekt wieder auf." }
entries[550] = { ["name"] = "Gift neutralisieren", ["text"] = "100 Mana 30 Meter Reichweite\nSofort\nDas Ziel ist 30 Sek. lang gegen Gift immun und wird von allen bereits vorhandenen Giften geheilt." }
entries[556] = { ["name"] = "Astraler Rückruf", ["text"] = "5.9% von GrundmanaWirken in 10 sek. 15 min Abklingzeit\nReißt den Zaubernden durch den Wirbelnden Nether zurück [ Glyphe 'Astrale Fixierung' : zum Erdschrein Eurer Fraktion / nach Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.]" }
entries[568] = { ["name"] = "Arkane Wucht", ["text"] = "Sofort\nFügt allen Gegnern innerhalb von 10 Metern 4050 bis 4950 Arkanschaden, verringert ihr Bewegungstempo um 70% und stößt sie zurück." }
entries[578] = { ["name"] = "Schwarzer Wolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren schwarzen Wolf oder gibt ihn wieder frei." }
entries[579] = { ["name"] = "Roter Wolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren roten Wolf oder gibt ihn wieder frei." }
entries[580] = { ["name"] = "Waldwolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Waldwolf oder gibt ihn wieder frei." }
entries[581] = { ["name"] = "Winterwolf", ["text"] = "Wirken in 1.5 sek.\nBeschwört einen reitbaren Winterwolf oder gibt ihn wieder frei." }
entries[585] = { ["name"] = "Heilige Pein", ["text"] = "2.7% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nZerschmettert einen Feind und fügt ihm 2361 Heiligschaden zu. [ Glyphe 'Heilige Pein' : Wenn das Ziel von Eurem Zauber 'Heiliges Feuer' betroffen ist, wird der Schaden von 'Heilige Pein' um 20% erhöht ] [ Wenn das Ziel von Eurem Zauber 'Machtwort: Trost' betroffen ist, wird der Schaden von 'Heilige Pein' um 20% erhöht ]" }
entries[586] = { ["name"] = "Verblassen", ["text"] = "3.5% von Grundmana\nSofort 30 sek. Abklingzeit\nLässt Euch verblassen und entfernt so zeitweilig Eure gesamte Bedrohung. [ Glyphe 'Schleier' : Zudem wird Euer erlittener Schaden um 10% verringert ] Hält 10 Sek. lang an. [ Phantom : Wenn Ihr verblasst, befreit Ihr Euch von allen bewegungseinschränkenden Effekten und Euer Bewegungstempo kann 5 Sek. lang nicht eingeschränkt werden. ]" }
entries[588] = { ["name"] = "Inneres Feuer", ["text"] = "Sofort\nDer Zaubernde wird von einem Schub heiliger Energie erfüllt, der seinen durch Gegenstände erhaltenen Rüstungswert um 60 % und seine Zaubermacht um 10% erhöht. [ Innerer Wille : Es kann nur entweder 'Innerer Wille' oder 'Inneres Feuer' aktiv sein ]" }
entries[589] = { ["name"] = "Schattenwort: Schmerz", ["text"] = "4.4% von Grundmana 40 Meter Reichweite\nSofort\nEin Wort der Dunkelheit, das sofort 780 Schattenschaden sowie im Verlauf von 18 Sek. zusätzlich ( 4678 - 780 ) Schattenschaden verursacht." }
entries[596] = { ["name"] = "Gebet der Heilung", ["text"] = "4.5% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nEin machtvolles Gebet heilt alle Gruppenmitglieder des befreundeten Ziels in einem Umkreis von 30 Metern um 8689 ." }
entries[603] = { ["name"] = "Verdammnis", ["text"] = "60 Dämonischer Furor 40 Meter Reichweite\nSpontanzauber\nVerflucht das Ziel mit drohender Verdammnis, die im Verlauf von 1 Min. 4006 Schattenschaden verursacht.\n\nWenn 'Verdammnis' einen kritischen Treffer erzielt, wird ein Wildwichtel beschworen, der das Ziel angreift." }
entries[605] = { ["name"] = "Gedankenkontrolle", ["text"] = "2% von Grundmana 30 Meter Reichweite\nWirken in 1.8 sek." }
entries[606] = { ["name"] = "Gedankenverfall", ["text"] = "240 Mana 30 Meter Reichweite\nWirken in 2 sek.\nEntzieht dem Ziel 30 Sek. lang insgesamt 2160 Mana." }
entries[611] = { ["name"] = "Siegel der Aufopferung", ["text"] = "Wirken in 3 sek." }
entries[633] = { ["name"] = "Handauflegung", ["text"] = "40 Meter Reichweite\nSofort 10 min Abklingzeit\nHeilt ein befreundetes Ziel um einen Betrag, der Eurer maximalen Gesundheit entspricht [ Glyphe 'Göttlichkeit' : zudem regeneriert Ihr 10% Eures maximalen Manas ].\n\nKann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 1 Min. lang anhält." }
entries[635] = { ["name"] = "Heiliges Licht", ["text"] = "12.6% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt ein befreundetes Ziel um 8869 ." }
entries[642] = { ["name"] = "Gottesschild", ["text"] = "Sofort 5 min Abklingzeit\nSchützt Euch 8 Sek. lang vor jeglichem Schaden und Zaubern, verringert jedoch Euren verursachten Schaden um 50%.\n\nKann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 1 Min. lang anhält." }
entries[668] = { ["name"] = "Sprache Globalisch" }
entries[669] = { ["name"] = "Sprache Orcisch" }
entries[670] = { ["name"] = "Sprache Taurisch" }
entries[671] = { ["name"] = "Sprache Darnassisch" }
entries[672] = { ["name"] = "Sprache Zwergisch" }
entries[673] = { ["name"] = "Geringe Verteidigung", ["text"] = "Sofort\nErhöht Eure Rüstung 1 Stunde lang um 50 . Wächterelixier." }
entries[674] = { ["name"] = "Beidhändigkeit", ["text"] = "Ermöglicht die Verwendung von Einhandwaffen und Schildhandwaffen in der Schildhand." }
entries[676] = { ["name"] = "Entwaffnen", ["text"] = "Nahkampfreichweite\nSofort 1 min Abklingzeit\nEntwaffnet den Gegner 8 Sek. lang, sodass dieser seine Waffe und seinen Schild zeitweilig verliert. Entwaffnete Kreaturen verursachen deutlich weniger Schaden." }
entries[686] = { ["name"] = "Schattenblitz", ["text"] = "40 Dämonischer Furor / 5.5% von Grundmana 40 Meter Reichweite\nWirken in 1.7 sek.\nSchleudert einen Schattenblitz auf den Gegner, der 1 Schattenschaden verursacht." }
entries[688] = { ["name"] = "Wichtel beschwören", ["text"] = "20% von Grunddämonischer furor / 20% von Grundmana\nWirken in 5 sek.\nBeschwört einen Wichtel, der unter dem Befehl des Hexenmeisters steht.\n\nWichtel wirken den Distanzzauber 'Feuerblitz' [ Wichtel: Meister kauterisieren : können ihren Meister im Verlauf der Zeit heilen ] [ Wichtel: Magie versengen : schädliche Magieeffekte läutern ] . [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]" }
entries[689] = { ["name"] = "Blutsauger", ["text"] = "1% von Grundmana , plus 1% pro Sekunde 40 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nEntzieht dem Ziel Leben, wodurch es alle 1 Sek. ( 357 + 0.334 * Zaubermacht) Schattenschaden erleidet und der Zaubernde 2% seiner gesamten Gesundheit regeneriert. Hält 6 Sek. lang an. [ Seelenbrand : Seelenbrand:\nErhöht den Heilungseffekt um 50%. ]" }
entries[691] = { ["name"] = "Teufelsjäger beschwören", ["text"] = "20% von Grunddämonischer furor / 25% von Grundmana\nWirken in 5 sek.\nBeschwört einen Teufelsjäger, der unter dem Befehl des Hexenmeisters steht.\n\nTeufelsjäger werden von Magie angezogen [ Teufelsjäger: Zaubersperre : unterbrechen das Wirken von Zaubern ] und können sich selbst heilen, indem sie auf das gegnerische Ziel wirkende magische Stärkungszauber aufzehren. [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]" }
entries[697] = { ["name"] = "Leerwandler beschwören", ["text"] = "20% von Grunddämonischer furor / 25% von Grundmana\nWirken in 5 sek.\nBeschwört einen Leerwandler, der unter dem Befehl des Hexenmeisters steht.\n\nLeerwandler können schwerem Schaden widerstehen [ Leerwandler: Entwaffnen : Nahkampfangreifer entwaffnen ] [ Leerwandler: Schattenschild : angreifenden Gegnern Schattenschaden zufügen ] [ Leerwandler: Schattenbollwerk : ihre Gesundheit erhöhen, wenn ihnen der Tod bevorsteht ] [ Leerwandler: Leiden : und Gegner verspotten, die ihren Meister angreifen / . ] [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]" }
entries[698] = { ["name"] = "Ritual der Beschwörung", ["text"] = "4% von Grundmana 30 Meter Reichweite\nKanalisiert (Wirken in 2 min) 2 min Abklingzeit\nFührt ein Ritual zur Erschaffung eines Beschwörungsportals durch, das von Verbündeten benutzt werden kann, um ein ausgewähltes Gruppen- oder Schlachtzugsmitglied zu beschwören.\n\nRituale\nZur Vervollständigung des Zaubers werden der Zaubernde und zwei weitere Verbündete benötigt." }
entries[700] = { ["name"] = "Schlaf", ["text"] = "60 Mana 30 Meter Reichweite\nWirken in 1.5 sek." }
entries[703] = { ["name"] = "Erdrosseln", ["text"] = "45 Energie Nahkampfreichweite\nSofort\nBenötigt Verstohlenheit\nErdrosselt den Gegner, bringt ihn 3 Sek. lang zum Schweigen und verursacht im Verlauf von 18 Sek. [( 147 + Angriffskraft * 0.078) * 6] Schaden, erhöht durch Eure Angriffskraft. Muss im Verstohlenheitsmodus sein. Gewährt 1 Combopunkt [ Mantel und Degen : und lässt Euch hinter dem Ziel erscheinen ]." }
entries[710] = { ["name"] = "Verbannen", ["text"] = "30 Dämonischer Furor / 3% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nVerbannt bis zu 30 Sek. lang einen gegnerischen Dämon, Elementar oder eine gegnerische Entartung.\n\nVerbannt\nVerhindert alle Aktionen des Ziels, macht es jedoch unverwundbar. Es kann immer nur jeweils eine Verbannung aktiv sein.\n\nWenn 'Verbannung' erneut gewirkt wird, wird der bestehende Effekt abgebrochen." }
entries[712] = { ["name"] = "Sukkubus beschwören", ["text"] = "20% von Grunddämonischer furor / 25% von Grundmana\nWirken in 5 sek.\nBeschwört einen Sukkubus, der unter dem Befehl des Hexenmeisters steht.\n\nSukkuben sind gefährliche Magier, die den Nahkampf bevorzugen. Sie können [ Sukkubus: Geringe Unsichtbarkeit : unsichtbar werden ] [ Sukkubus: Peitschen : Ziele zurückstoßen ] [ Sukkubus: Geringe Unsichtbarkeit : und ] humanoide Gegner betören, die dadurch nicht angreifen können. [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]" }
entries[713] = { ["name"] = "Inkubus beschwören", ["text"] = "25% von Grundmana / 20% von Grunddämonischer furor\nWirken in 5 sek.\nBeschwört einen Inkubus, der unter dem Befehl des Hexenmeisters steht.\n\nInkuben sind gefährliche Zauberwirker, die aus kurzer Distanz angreifen. Sie können sich [ Sukkubus: Geringe Unsichtbarkeit : unsichtbar machen ] [ Sukkubus: Peitschen : Gegner wegstoßen ] [ Sukkubus: Geringe Unsichtbarkeit : und ] humanoide Kreaturen verführen, was sie am Angreifen hindert. [ Seelenbrand : Seelenbrand:\nSpontanzauber. ]" }
entries[720] = { ["name"] = "Umschlingen", ["text"] = "Sofort\nDie Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und macht es 8 Sek. lang bewegungsunfähig." }
entries[724] = { ["name"] = "Lichtbrunnen", ["text"] = "5.4% von Grundmana 40 Meter Reichweite\nWirken in 0.5 sek. 3 min Abklingzeit\nErschafft einen heiligen Lichtbrunnen. Verbündete Spielercharaktere können den Lichtbrunnen anklicken, um 6 Sek. lang alle 2 Sek. um [(( 5735 + (Zaubermacht * .553))) * 1.5] Gesundheit geheilt zu werden. Erlittene Angriffe, die 30% Eurer Gesamtgesundheit entsprechen, heben diesen Effekt auf. Der Lichtbrunnen bleibt 3 Min. oder 15 Aufladungen lang bestehen." }
entries[731] = { ["name"] = "Umschlingen", ["text"] = "Sofort\nDie Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und macht es 8 Sek. lang bewegungsunfähig." }
entries[740] = { ["name"] = "Gelassenheit", ["text"] = "27.1% von GrundmanaKanalisiert (Wirken in 8 sek.) 8 min Abklingzeit\nHeilt die 5 (12 in 25 - Spieler - Instanzen) Gruppen- oder Schlachtzugsmitglieder innerhalb von 40 Metern, deren Gesundheit am niedrigsten ist, 8 Sek. lang alle 2 Sek. um 9037 Gesundheit.\n\nZusätzlich heilt 'Gelassenheit' 8 Sek. lang alle 2 Sek. um 1 Gesundheit. Bis zu 3-mal stapelbar. Der Druide muss seine Kräfte kanalisieren, um den Zauber aufrechtzuerhalten." }
entries[742] = { ["name"] = "Pulverisieren", ["text"] = "10 min Abklingzeit\n(Procchance: 35%)" }
entries[744] = { ["name"] = "Gift", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Gegner 15 Sek. lang alle 3 Sek. Naturschaden zu." }
entries[745] = { ["name"] = "Gespinst", ["text"] = "30 Meter Reichweite\nSofort\nZaubert ein Netz über einen Feind und macht ihn so 5 Sek. lang bewegungsunfähig." }
entries[746] = { ["name"] = "Erste Hilfe", ["text"] = "15 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nHeilt im Verlauf von 6 Sek. 66 Schaden." }
entries[747] = { ["name"] = "Abbilder beschwören", ["text"] = "Sofort\nBeschwört 2 Kopien des Zaubernden." }
entries[750] = { ["name"] = "Plattenpanzer", ["text"] = "Gestattet Euch, Gegenstände der Kategorie 'Plattenrüstung' anzulegen." }
entries[755] = { ["name"] = "Lebenslinie", ["text"] = "45 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nOpfert 2% Eurer gesamten Gesundheit, um Euren beschworenen Dämon alle 1 Sek. um 6% seiner gesamten Gesundheit zu heilen. Hält 6 Sek. lang an.\n[\nMachterfüllte Kanalisierung\nWenn dieser Zauber erneut gewirkt wird, bevor seine Effektdauer endet, wird die Effektdauer um 0.05 Sek. erhöht.\nBis zu 0-mal stapelbar. ] [ Seelenbrand: Lebenslinie : Seelenbrand:\nRegeneriert 140% mehr Gesundheit und verringert den erlittenen Schaden 10 Sek. lang um 30%. ]" }
entries[759] = { ["name"] = "Manaedelstein herbeizaubern", ["text"] = "18% von Grundmana\nWirken in 3 sek.\nZaubert einen Manaedelstein herbei, der [ Glyphe 'Ungebundenes Mana' : im Verlauf von bis Abbruch 0 Mana wiederherstellt / sofort 45000 Mana wiederherstellt] und bis zu 3 Aufladungen hat.\n\nHerbeigezauberte Gegenstände\nHerbeigezauberte Gegenstände verschwinden, wenn Ihr Euch länger als 15 Min. ausloggt." }
entries[768] = { ["name"] = "Katzengestalt", ["text"] = "3.7% von Grundmana\nSofort\nVerwandelt Eure Gestalt in die einer Katze und bewirkt, dass Beweglichkeit die Angriffskraft erhöht, erhöht den von Euren automatischen Angriffen verursachten Schaden um 100% und Euer Bewegungstempo um 25% (kumulativ mit den meisten anderen Beschleunigungseffekten). [ Glyphe 'Katzengestalt' : Erhöht außerdem sämtliche von Euch erhaltene Heilung um 20% ]\nBeschützt Euch außerdem vor Verwandlungseffekten und erlaubt den Einsatz von verschiedenen Katzenfähigkeiten.\n\nEnergieregeneration dauert an, während Ihr Euch nicht in Katzengestalt befindet.\n\nDer Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten." }
entries[770] = { ["name"] = "Feenfeuer", ["text"] = "7.5% von Grundmana 35 Meter Reichweite\nSofort\nFeen tummeln sich um das Ziel, hindern es daran, Verstohlenheit einzusetzen oder unsichtbar zu werden, und belegen es mit 3 Stapeln des Effekts 'Rüstungsschwächung'.\n\nVerursacht 10 Schaden, [ Glyphe 'Feenstille' : bringt das Ziel 3 Sek. lang zum Schweigen ] und gewährt eine Chance von 25%, die Abklingzeit von 'Zerfleischen' abzuschließen, wenn es in Bärengestalt gewirkt wird.\n\nRüstungsschwächung\nSchwächt die Rüstung des Ziels 30 Sek. lang um 4%. Bis zu 3-mal stapelbar." }
entries[774] = { ["name"] = "Verjüngung", ["text"] = "14.5% von Grundmana 40 Meter Reichweite\nSofort\nHeilt das Ziel um 1 und zusätzlich 12 Sek. lang alle 3 Sek. um 1 ." }
entries[779] = { ["name"] = "Prankenhieb", ["text"] = "15 Wut 8 Meter Reichweite\nSpontanzauber 3 sek. Abklingzeit\nBenötigt Bärengestalt\nSchlägt Gegner in der Nähe und verursacht so 246 Schaden.\n\nFügt blutenden Zielen 20% zusätzlichen Schaden zu." }
entries[781] = { ["name"] = "Rückzug", ["text"] = "Unbegrenzte Reichweite\nSofort 20 sek. Abklingzeit\nIhr versucht, rückwärts zu springen. [ Impromptu : Außerdem werdet Ihr von bewegungseinschränkenden Effekten befreit und Euer Bewegungstempo wird 8 Sek. lang um 60% erhöht ] [ Um ein Haar : Es wird gleichzeitig eine Netzfalle aktiviert, die alle Ziele im Umkreis von 8 Metern mit klebrigen Netzen bedeckt. Diese Netze machen alle Ziele 8 Sek. lang bewegungsunfähig ] [ Glyphe 'Befreiung' : Zusätzlich werdet Ihr um 5% Eurer gesamten Gesundheit geheilt ]" }
entries[783] = { ["name"] = "Reisegestalt", ["text"] = "5.6% von Grundmana\nSofort\nVerwandelt Euch in eine Reisegestalt und erhöht Euer Bewegungstempo um 40%. Beschützt Euch außerdem vor Verwandlungseffekten. Kann nur im Freien verwendet werden.\n\nDer Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten." }
entries[785] = { ["name"] = "Wahre Erfüllung", ["text"] = "260 Mana 45 Meter Reichweite\nWirken in 0.5 sek.\nVon den Kräften des Propheten Skeram bekehrt, wird das Ziel mit heiliger Macht erfüllt. Die Zauber des Ziels werden sofort gewirkt, der verursachte Schaden ist um 300%, alle Widerstände sind um 50 und das Bewegungstempo ist um 40% erhöht. Hält 20 Sek. lang an." }
