entries[802] = { ["name"] = "Käfer mutieren", ["text"] = "30 Meter Reichweite\nSofort\nErhöht die Gesundheit und den verursachten Schaden eines nahen Skarabäus." }
entries[804] = { ["name"] = "Käfer explodieren lassen", ["text"] = "30 Meter Reichweite\nSofort\nErfüllt einen Skarabäus mit Energie und lässt ihn nach Ablauf von 3 Sek. explodieren." }
entries[806] = { ["name"] = "Inbrunst", ["text"] = "Sofort\nErhöht Stärke um 14 und fügt Euch 1 Min. lang alle 15 Sek. 15 Schaden zu." }
entries[812] = { ["name"] = "Regelmäßiger Manabrand", ["text"] = "Unbegrenzte Reichweite\nSofort\nWirkt in regelmäßigen Abständen Manabrand." }
