entries[845] = { ["name"] = "Spalten", ["text"] = "30 Wut Nahkampfreichweite\nSpontanzauber 1.5 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin weitreichender Angriff, der das Ziel sowie ein weiteres in der Nähe trifft. Verursacht 82% Waffenschaden (115%, wenn eine Einhandwaffe ausgerüstet ist) [ Glyphe 'Verwehrende Stöße' : und verringert das Bewegungstempo des Ziels 8 Sek. lang um 50% ].\n\nSetzt diese Fähigkeit ein, wenn Ihr überschüssige Wut zur Verfügung habt." }
entries[851] = { ["name"] = "Verwandlung: Schaf", ["text"] = "200 Mana 20 Meter Reichweite\nSofort\nVerwandelt den Feind bis zu 10 Sek. lang in ein hilfloses Schaf, das weder Zauber wirken noch angreifen kann und sich um 60% langsamer bewegt." }
entries[853] = { ["name"] = "Hammer der Gerechtigkeit", ["text"] = "3.5% von Grundmana 10 Meter Reichweite\nSofort 1 min Abklingzeit\nBetäubt das Ziel 6 Sek. lang." }
entries[871] = { ["name"] = "Schildwall", ["text"] = "Sofort 3 min Abklingzeit\nVerringert sämtlichen erlittenen Schaden 12 Sek. lang um 40%." }
entries[879] = { ["name"] = "Exorzismus", ["text"] = "4% von Grundmana 30 Meter Reichweite\nSofort 15 sek. Abklingzeit\nVersucht, mit einem Schub heiligen Lichts das Böse aus dem Ziel zu vertreiben. Verursacht 6960 Heiligschaden und erzeugt eine Aufladung heiliger Kraft." }
entries[883] = { ["name"] = "Begleiter 1 rufen", ["text"] = "Sofort\nBeschwört Euer erstes Tier zu Euch." }
entries[886] = { ["name"] = "Unsichtbarkeit", ["text"] = "Wirken in 3 sek.\nLehrt 'Unsichtbarkeit'." }
