entries[898] = { ["name"] = "Inbrunsttrank herstellen", ["text"] = "Wirken in 3 sek.\nReagenzien:\nFaustgroße Spinndrüse\nStellt einen Trank der Inbrunst her." }
entries[921] = { ["name"] = "Taschendiebstahl", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Verstohlenheit\nEinen Taschendiebstahl am Ziel begehen." }
entries[932] = { ["name"] = "Geist auffüllen II", ["text"] = "30 Meter ReichweiteWirken in 3 sek. 6 min Abklingzeit\nStellt Mana des Ziels wieder her." }
entries[952] = { ["name"] = "Gletscher" }
entries[974] = { ["name"] = "Erdschild", ["text"] = "19% von Grundmana 40 Meter Reichweite\nSofort\nSchützt das Ziel mit einem Erdschild, der die Effektivität schamanischer Heilzauber bei diesem Ziel um 20% erhöht und das geschützte Ziel bei Angriffen um ( 2043 + Zaubermacht * 0.13) heilt. 9 Aufladungen. Hält 10 Min. lang an. Dieser Effekt tritt nur einmal alle paar Sekunden auf.\n\n'Erdschild' kann immer nur auf einem Ziel gleichzeitig aktiv sein, auf jedem Ziel kann nur ein Erdschild aktiv sein und es kann immer nur eins der Elementarschilde auf dem Schamanen aktiv sein.\n(3.5s Abklingzeit)" }
entries[980] = { ["name"] = "Agonie", ["text"] = "1% von Grundmana 40 Meter Reichweite\nSofort\nFügt dem Ziel immer stärkere Schmerzen zu, die im Verlauf von 24 Sek. bis zu ( 327 * 10) Schattenschaden verursachen.\n\nZunächst wird nur geringer Schaden verursacht, der aber mit jedem Tick zunimmt." }
entries[982] = { ["name"] = "Tier wiederbeleben", ["text"] = "35 Fokus\nWirken in 4 sek.\nBringt Euer totes Tier mit 100% seiner Grundgesundheit wieder ins Leben zurück." }
entries[1022] = { ["name"] = "Hand des Schutzes", ["text"] = "7% von Grundmana 40 Meter Reichweite\nSofort 5 min Abklingzeit\nLegt eine Hand auf ein Gruppen- oder Schlachtzugsmitglied und schützt es 10 Sek. lang vor allen körperlichen Angriffen, allerdings kann es dabei weder angreifen noch körperliche Fähigkeiten einsetzen. Spielercharaktere können pro Paladin immer nur von einer Hand berührt werden.\n\nKann nicht auf Ziele gewirkt werden, die von 'Vorahnung' betroffen sind. Ruft den Effekt 'Vorahnung' hervor, der 1 Min. lang anhält." }
entries[1038] = { ["name"] = "Hand der Erlösung", ["text"] = "6% von Grundmana 40 Meter Reichweite\nSofort 2 min Abklingzeit\nLegt eine Hand auf das Gruppen- oder Schlachtzugsmitglied, die seine gesamte Bedrohung 10 Sek. lang entfernt. Spielercharaktere können pro Paladin immer nur von einer Hand berührt werden." }
entries[1044] = { ["name"] = "Hand der Freiheit", ["text"] = "7% von Grundmana 40 Meter Reichweite\nSofort 25 sek. Abklingzeit\nLegt eine Hand auf ein verbündetes Ziel und gewährt ihm so 6 Sek. lang Immunität gegen jegliche bewegungseinschränkenden Effekte. Spielercharaktere können pro Paladin immer nur von einer Hand berührt werden." }
entries[1050] = { ["name"] = "Opferung", ["text"] = "Wirken in 1 sek." }
entries[1064] = { ["name"] = "Kettenheilung", ["text"] = "22.5% von Grundmana 40 Meter Reichweite\nWirken in 2.5 sek.\nHeilt das befreundete Ziel um 7590 und springt dann weiter, um die am schwersten verletzten Ziele in der Nähe zu heilen. Wenn der Zauber auf ein Gruppenmitglied gewirkt wird, springt die Heilung nur auf andere Gruppenmitglieder über. [ Wiederherstellung : Außerhalb von Arenen und Schlachtfeldern verringert sich die Heilwirkung mit jedem Sprung um 20% ] Heilt insgesamt 4 Ziele." }
entries[1066] = { ["name"] = "Wassergestalt", ["text"] = "5.6% von Grundmana\nSofort\nVerwandelt Euch in eine Wassergestalt. Das Schwimmtempo wird um 50% erhöht und Ihr könnt unter Wasser atmen. Beschützt Euch außerdem vor Verwandlungseffekten.\n\nDer Akt des Gestaltwandelns befreit Euch von bewegungseinschränkenden Effekten." }
entries[1079] = { ["name"] = "Zerfetzen", ["text"] = "30 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der im Lauf der Zeit Blutungsschaden verursacht. Der Schaden erhöht sich pro Combopunkt:\n\n1 Punkt: [floor(((((4 + (Angriffskraft * 0.0484)))) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] Schaden im Verlauf von 16 Sek.\n2 Punkte: [floor(((((4 + (Angriffskraft * 0.0484))) * 2) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] Schaden im Verlauf von 16 Sek.\n3 Punkte: [floor(((((4 + (Angriffskraft * 0.0484))) * 3) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] Schaden im Verlauf von 16 Sek.\n4 Punkte: [floor(((((4 + (Angriffskraft * 0.0484))) * 4) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] Schaden im Verlauf von 16 Sek.\n5 Punkte: [floor(((((4 + (Angriffskraft * 0.0484))) * 5) * (( 1 * 1 * 1 * 1 * 1 ))) + 113 ) * 8] Schaden im Verlauf von 16 Sek.\n\nJedes Mal, wenn Ihr in Katzengestalt Eure Fähigkeiten 'Schreddern', 'Verheeren' oder 'Zerfleischen' einsetzt, wird die Dauer eines bestehenden Effekts von 'Zerfetzen' auf dem Ziel um 2 Sek. erhöht, bis zu einem Maximum von 6 Sek." }
entries[1090] = { ["name"] = "Schlaf", ["text"] = "90 Mana 30 Meter Reichweite\nWirken in 1.5 sek." }
entries[1098] = { ["name"] = "Dämon unterwerfen", ["text"] = "5% von Grundmana 30 Meter Reichweite\nWirken in 3 sek.\nUnterwirft den Zieldämon und zwingt ihn, Euch zu dienen. Hält bis zu 5 Min. lang an.\n\nUnterworfen\nWährend der Dämon unterworfen ist, wird die Zeit zwischen seinen Angriffen um 30% erhöht und sein Zaubertempo um 20% verlangsamt." }
entries[1120] = { ["name"] = "Seelendieb", ["text"] = "1.5% von Grundmana , plus 1.5% pro Sekunde 40 Meter Reichweite\nKanalisiert (Wirken in 12 sek.)\nEntzieht dem Ziel die Seele, wodurch es alle 2 Sek. ( 275 + Zaubermacht * 0.257) Schattenschaden erleidet und nach jedem zweiten Schaden verursachenden Tick ein Seelensplitter aufgefüllt wird. Wenn das Ziel stirbt und Erfahrung oder Ehre gewährt, werden 4 Seelensplitter aufgefüllt. Hält 12 Sek. lang an.\n\nWenn das Ziel über 20% Gesundheit oder weniger verfügt, verursacht 'Seelenentzug' 100% zusätzlichen Schaden und lässt alle Eure anderen regelmäßigen Gebrechenseffekte sofort 60% ihres normalen regelmäßigen Schadens verursachen." }
entries[1121] = { ["name"] = "Umschlingen", ["text"] = "100 Meter Reichweite\nSofort\nDie Brutstätte Fankriss' des Unnachgiebigen zieht das Ziel nahen Silithidjungtieren entgegen und macht es 8 Sek. lang bewegungsunfähig." }
entries[1122] = { ["name"] = "Höllenbestie beschwören", ["text"] = "25% von Grundmana 30 Meter Reichweite\nSofort 10 min Abklingzeit\nBeschwört einen Meteor aus dem Wirbelnden Nether, der allen Gegnern im Zielgebiet 1069 Feuerschaden zufügt und sie 2 Sek. lang betäubt. Aus dem Krater erhebt sich eine Höllenbestie, die 1 Min. lang unter dem Befehl des Zaubernden steht.\n\nDie Höllenbestie verursacht schweren Flächenschaden und wird Ziele in der Nähe des Einschlagsortes angreifen." }
entries[1126] = { ["name"] = "Mal der Wildnis", ["text"] = "5% von Grundmana 30 Meter Reichweite\nSofort\nErhöht die Stärke, Beweglichkeit und Intelligenz des verbündeten Ziels für 1 Stunde um 5%.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten." }
entries[1127] = { ["name"] = "Essen", ["text"] = "Sofort\nStellt im Verlauf von 25 Sek. insgesamt ( 325 * 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[1129] = { ["name"] = "Essen", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. insgesamt 1711 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[1130] = { ["name"] = "Mal des Jägers", ["text"] = "100 Meter Reichweite\nSofort\nBelegt das Ziel mit dem Mal des Jägers, das den Distanzschaden aller Angreifer gegen dieses Ziel um 5% erhöht. Das Ziel kann immer vom Jäger gesehen und aufgespürt werden.\n\nDie Fähigkeiten 'Arkaner Schuss', 'Schimärenschuss', 'Fass!' und 'Explosivschuss' rufen automatisch den Effekt von 'Mal des Jägers' hervor.\n\nHält 5 Min. lang an." }
entries[1131] = { ["name"] = "Essen", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. insgesamt 2792 Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[1132] = { ["name"] = "Kritischer Treffer" }
entries[1133] = { ["name"] = "Trinken", ["text"] = "Sofort\nStellt im Verlauf von 27 Sek. insgesamt ( 249 / 5 * 27) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[1135] = { ["name"] = "Trinken", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. insgesamt ( 332 / 5 * 30) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[1137] = { ["name"] = "Trinken", ["text"] = "Sofort\nStellt im Verlauf von 30 Sek. insgesamt ( 489 / 5 * 30) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[1138] = { ["name"] = "Kristallschutz", ["text"] = "30 Meter Reichweite\nSofort\nVerstärkt Frost- und Schattenwiderstand 1 Min. lang um 10." }
entries[1139] = { ["name"] = "Kaltauge", ["text"] = "30 Meter Reichweite\nSofort\nErhöht 15 Sek. lang die Zeit zwischen Angriffen des Ziels um 5%." }
entries[1159] = { ["name"] = "Erste Hilfe", ["text"] = "15 Meter Reichweite\nKanalisiert (Wirken in 6 sek.)\nHeilt im Verlauf von 6 Sek. 114 Schaden." }
entries[1160] = { ["name"] = "Demoralisierender Ruf", ["text"] = "Sofort 1 min Abklingzeit\nDemoralisiert alle Gegner im Umkreis von 10 Metern und verringert 10 Sek. lang den Schaden, den sie dem schreienden Krieger zufügen, um 20%." }
entries[1178] = { ["name"] = "Bear Form Passive", ["text"] = "Benötigt Bärengestalt\nModifies Power Cost -100%:\nFeenfeuer\n\nModifies Cooldown +6000:\nFeenfeuer , Feenschwarm" }
entries[1180] = { ["name"] = "Dolche" }
entries[1234] = { ["name"] = "Tony's God Mode", ["text"] = "Unbegrenzte Reichweite\nSofort 0.5 sek. Abklingzeit\nTödlicher Schaden wird absorbiert.\nGesundheit um 100% erhöht.\nHeilt alle 5 100% Gesundheit." }
entries[1329] = { ["name"] = "Verstümmeln", ["text"] = "55 Energie Nahkampfreichweite\nSofort\nGreift sofort mit beiden Waffen an und verursacht 280% Waffenschaden sowie mit jeder Waffe zusätzlich 312 Schaden. Gewährt 2 Combopunkte." }
entries[1330] = { ["name"] = "Erdrosseln - Stille", ["text"] = "Unbegrenzte Reichweite\nSofort\nBringt das Ziel 3 Sek. lang zum Schweigen." }
entries[1364] = { ["name"] = "Unerschütterlicher Wille" }
entries[1373] = { ["name"] = "'Teufelsjäger beschwören' lehren" }
entries[1386] = { ["name"] = "Echos von Lordaeron" }
entries[1446] = { ["name"] = "Wassergestalt" }
entries[1449] = { ["name"] = "Arkane Explosion", ["text"] = "3% von Grundmana\nSofort\nVerursacht eine Explosion arkaner Magie um den Zaubernden herum, die allen Zielen im Umkreis von 10 Metern 503 Arkanschaden zufügt. [ Arkane Aufladung : Frischt bestehende Arkane Aufladungen auf und hat eine Chance von 30%, eine Arkane Aufladung zu erzeugen, wenn mindestens ein Ziel getroffen wird ]" }
entries[1454] = { ["name"] = "Aderlass", ["text"] = "Sofort\n[ Glyphe 'Aderlass' : Belegt Euch mit einem stapelbaren Effekt, der bis Abbruch lang anhält sowie Heilung in Höhe von 15% Eurer gesamten Gesundheit absorbiert, und regeneriert sofort / Regeneriert sofort] (15 * Gesamtgesundheit * 0.01) Mana. [ Glyphe 'Aderlass' : Hält bis Abbruch lang an ]" }
entries[1459] = { ["name"] = "Arkane Brillanz", ["text"] = "1% von Grundmana 30 Meter Reichweite\nSofort\nErfüllt das Ziel mit Brillanz, erhöht 1 Stunde lang seine Zaubermacht um 10% und seine kritische Trefferchance um 5%.\n\nWenn sich das Ziel in Eurer Gruppe oder Eurem Schlachtzug befindet, werden alle Mitglieder den Effekt erhalten." }
entries[1462] = { ["name"] = "Wildtierkunde", ["text"] = "40 Meter Reichweite\nSofort\nSammelt Informationen über das Zielwildtier. Der Tooltip zeigt Schaden, Gesundheit, Rüstung, alle Spezialwiderstände und Ernährung an. Zusätzlich wird angezeigt, ob das Tier zähmbar ist und über welche Fähigkeiten die gezähmte Kreatur verfügt." }
entries[1463] = { ["name"] = "Schutz des Beschwörers", ["text"] = "Sofort 25 sek. Abklingzeit\nUmgibt Euch mit einem magischen Schutz, der 8 Sek. lang bis zu ( 1041 + Zaubermacht * 1.0) Schaden absorbiert. Der absorbierte Schaden stellt bis zu 18% Eures maximalen Manas wieder her.\n\nWenn dieser Effekt endet, erhaltet Ihr abhängig von der absorbierten Menge 25 Sek. lang um bis zu 15% erhöhten Zauberschaden.\n\nPassiv:\nErhöht Euren Zauberschaden um 6% und Eure Manaregeneration um 65%. Dieser Effekt ist inaktiv, während der Zauber 'Schutz des Beschwörers' abklingt." }
entries[1464] = { ["name"] = "Zerschmettern", ["text"] = "25 Wut Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nZerschmettert den Gegner und fügt ihm so 275% Waffenschaden plus 1246 zu. [ Kolossales Schmettern : Fügt Gegnern, die vom Effekt Eurer Fähigkeit 'Kolossales Schmettern' betroffen sind, zusätzlich 10% Schaden zu ] [ Weitreichende Stöße : Während 'Weitreichende Stöße' aktiv ist, werden 35% des von 'Zerschmettern' verursachten Schadens auch allen anderen Gegnern im Umkreis von 2 Metern zugefügt ]" }
entries[1485] = { ["name"] = "Rollender Brocken", ["text"] = "Unbegrenzte Reichweite\nWirken in 2 sek.\nFeuert mit einer Distanzwaffe auf das Ziel." }
entries[1490] = { ["name"] = "Fluch der Elemente", ["text"] = "4% von Grundmana 40 Meter Reichweite\nSofort\nVerflucht das Ziel [ Glyphe 'Fluch der Elemente' : und 2 zusätzliche Ziele in der Nähe ], wodurch der erlittene Magieschaden 5 Min. lang um 5% erhöht wird.\n\nFlüche\nEs kann pro Ziel immer nur jeweils ein Fluch des Hexenmeisters aktiv sein. [ Seelenbrand: Fluch : Seelenbrand:\nEuer Zauber 'Fluch der Elemente' trifft alle Gegner im Umkreis von 10 Metern um Euer Ziel. ]" }
entries[1494] = { ["name"] = "Wildtiere aufspüren", ["text"] = "Sofort\nZeigt alle in der Nähe befindlichen Wildtiere auf der Minikarte an." }
entries[1499] = { ["name"] = "Eiskältefalle", ["text"] = "Sofort 30 sek. Abklingzeit\nPlatziert eine Eisfalle, die den ersten sich nähernden Gegner einfriert, wodurch er bis zu 1 Min. lang handlungsunfähig wird [ Glyphe 'Linderung' : zudem werden alle auf den Gegner wirkenden regelmäßigen Effekte entfernt ]. Jeglicher verursachte Schaden wird das Eis brechen. [ Glyphe 'Eiskältefalle' : Das Bewegungstempo des Ziels ists danach 4 Sek. lang um 70% verringert ] [ Glyphe 'Kein Entkommen' : Die kritische Trefferchance aller Eurer Distanzfähigkeiten gegen das eingefrorene Ziel wird um 100% erhöht, solang das Eis nicht gebrochen wurde ] Es kann immer nur jeweils ein Ziel gleichzeitig in Eis eingeschlossen werden. Die Falle bleibt 1 Min. lang bestehen." }
entries[1513] = { ["name"] = "Wildtier ängstigen", ["text"] = "25 Fokus 30 Meter Reichweite\nWirken in 1.5 sek.\nJagt einem Wildtier Angst ein, woraufhin es bis zu 20 Sek. lang voller Furcht wegläuft. Erlittener Schaden kann den Effekt unterbrechen. Es kann immer nur jeweils ein Wildtier mit dem Furchteffekt versehen werden." }
entries[1515] = { ["name"] = "Wildtier zähmen", ["text"] = "30 Meter Reichweite\nKanalisiert (Wirken in 10 sek.)\nBeginnt mit dem Zähmen eines Wildtiers, damit es Euer Gefährte wird. Falls Ihr die Aufmerksamkeit des Wildtiers aus irgendeinem Grund verlieren solltet, schlägt die Zähmung fehl." }
entries[1516] = { ["name"] = "Schnellschuss", ["text"] = "5 - 30 Meter Reichweite\n1 min Abklingzeit\nBenötigt Distanzwaffe\nFeuert Eure Waffe sofort ab und verursacht so 5 zusätzlichen Schaden." }
entries[1528] = { ["name"] = "Meister befreien", ["text"] = "5 Meter Reichweite\nSofort\nBefreit Euren Meister von allen Fesseln." }
entries[1535] = { ["name"] = "Feuernova", ["text"] = "13.7% von Grundmana 100 Meter Reichweite\nSofort 4 sek. Abklingzeit\nZündet alle auf nahe Feinde wirkenden Effekte Eures Zaubers 'Flammenschock', sodass jedes betroffene Ziel eine Flammenwelle ausstößt, welche allen weiteren Zielen im Umkreis von 10 Metern 1 Feuerschaden zufügt." }
entries[1536] = { ["name"] = "Langschuss II" }
entries[1538] = { ["name"] = "Laden", ["text"] = "20 Meter Reichweite\nWirken in 5 sek.\nLädt die Rute von Helcular auf, wenn sie an drei zeremoniellen Scheiterhaufen benutzt wird." }
entries[1539] = { ["name"] = "Tier füttern", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerfüttert Eurem Tier die ausgewählte Speise, wodurch es 50% seiner gesamten Gesundheit regeneriert. Kann nicht im Kampf angewandt werden." }
entries[1543] = { ["name"] = "Leuchtfeuer", ["text"] = "40 Meter Reichweite\nSofort 20 sek. Abklingzeit\nGibt 20 Sek. alle verborgenen und unsichtbaren Feinde im Umkreis von 10 Metern um das Zielgebiet preis." }
entries[1557] = { ["name"] = "Volles Tempo", ["text"] = "Sofort\nErhöht Bewegungstempo um 300." }
entries[1588] = { ["name"] = "Tier-Ausbau" }
entries[1604] = { ["name"] = "Benommen", ["text"] = "Nahkampfreichweite\nSofort\nEin erschütternder Schlag, der das Ziel zum Absitzen zwingt und das Bewegungstempo um 50% verringert." }
entries[1609] = { ["name"] = "Kreissäge des Aschenbringers" }
