entries[1680] = { ["name"] = "Wirbelwind", ["text"] = "30 Wut\nSpontanzauber\nBenötigt Nahkampfwaffe\nIn einem stählernen Wirbel greift Ihr alle Gegner in einem Umkreis von 8 Metern [ Blutdurst : mit beiden Waffen ] an und fügt jedem Ziel 85% Waffenschaden zu." }
entries[1706] = { ["name"] = "Levitieren", ["text"] = "0.9% von Grundmana 30 Meter Reichweite\nSofort\nErmöglicht es dem befreundeten Gruppen- oder Schlachtzugsmitglied, ein wenig über dem Boden zu schweben. Beim Levitieren fällt das Ziel zudem mit verringertem Tempo und kann sich über Wasser bewegen. Jeglicher Schaden hebt den Effekt auf. Hält 10 Min. lang an." }
entries[1715] = { ["name"] = "Kniesehne", ["text"] = "10 Wut Nahkampfreichweite\nSpontanzauber 1 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nVerstümmelt den Feind und verringert so sein Bewegungstempo 15 Sek. lang um 50%." }
entries[1719] = { ["name"] = "Tollkühnheit", ["text"] = "Sofort 3 min Abklingzeit\nErhöht 12 Sek. lang die kritische Trefferchance Eurer Spezialfähigkeiten um 30%." }
entries[1725] = { ["name"] = "Ablenken", ["text"] = "30 Energie 30 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBewirkt eine Ablenkung, die die Aufmerksamkeit aller in der Nähe befindlichen Monster 10 Sek. lang auf sich zieht. Bricht Verstohlenheit nicht ab." }
entries[1742] = { ["name"] = "Ducken", ["text"] = "Sofort 45 sek. Abklingzeit\nEuer Tier duckt sich, wodurch sein erlittener Schaden 6 Sek. lang um 40% verringert wird. Während des Duckens ist das Bewegungstempo Eures Tiers um 50% verringert." }
entries[1752] = { ["name"] = "Finsterer Stoß", ["text"] = "50 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nEin sofortiger Stoß, der 192% normalen Waffenschaden plus 280 verursacht. [ Sinister Strike Enabler : Gewährt 0 Combopunkte ]" }
entries[1766] = { ["name"] = "Tritt", ["text"] = "Nahkampfreichweite\nSofort 15 sek. Abklingzeit\nEin schneller Tritt, der das Wirken von Zaubern unterbricht und 5 Sek. lang verhindert, dass diese Art Zauber gewirkt werden kann. [ Glyphe 'Tritt' : Wenn ein Zauber erfolgreich unterbrochen wird, wird die Abklingzeit von 'Tritt' um 6 Sek. verringert ]" }
entries[1776] = { ["name"] = "Solarplexus", ["text"] = "45 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nMacht ein Euch zugewandtes Ziel 4 Sek. lang handlungsunfähig. Jeglicher vom Ziel erlittene Schaden führt zu seiner Erholung." }
entries[1784] = { ["name"] = "Verstohlenheit", ["text"] = "Sofort 6 sek. Abklingzeit\nVerbirgt Euch in den Schatten, wodurch Ihr um Gegner herumschleichen könnt, ohne gesehen zu werden. [ Nachtpirscher : Das Bewegungstempo in der Verstohlenheit ist um 0% erhöht ] Hält an, bis die Aktion abgebrochen wird." }
