entries[1850] = { ["name"] = "Spurt", ["text"] = "Sofort 3 min Abklingzeit\nHebt sämtliche bewegungseinschränkenden Effekte auf und erhöht das Bewegungstempo in Katzengestalt 15 Sek. lang um 70%.\n\nBricht Verstohlenheit nicht ab.\n\nDer Einsatz dieser Fähigkeit aktiviert Katzengestalt." }
entries[1852] = { ["name"] = "Zum Schweigen gebracht", ["text"] = "Unbegrenzte Reichweite\nSofort\nDas ist ein GM-Tool, um Spieler stumm zu stellen. Dieser Zauber fungiert nur als visuelle Anzeige, damit der Spieler und der GM wissen, dass der Spieler gerade stumm gestellt ist." }
entries[1856] = { ["name"] = "Verschwinden", ["text"] = "Sofort 2 min Abklingzeit\nErmöglicht es Euch, sofort zu verschwinden und Euch 3 Sek. lang in einem verbesserten Verstohlenheitsmodus zu bewegen. Für die ersten 3 Sek. nach dem Verschwinden können weder Schaden noch schädliche Effekte die Verstohlenheit brechen. Bewegungseinschränkende Effekte werden beim Verschwinden entfernt." }
entries[1860] = { ["name"] = "Sicheres Fallen", ["text"] = "Verringert den Fallschaden." }
entries[1881] = { ["name"] = "Jungtier des Zaraschwarms beschwören" }
entries[1906] = { ["name"] = "Entkräftender Sturmangriff", ["text"] = "25 Meter Reichweite\nSofort\nStürmt auf einen Gegner zu, verursacht Schaden und verringert 8 Sek. lang sein Bewegungstempo um 60%." }
entries[1908] = { ["name"] = "Mächtige Heilung", ["text"] = "100 Meter Reichweite\nSofort\nHeilt das Ziel alle bis Abbruch Sek. komplett." }
entries[1936] = { ["name"] = "Teleport nach Ambossar" }
entries[1940] = { ["name"] = "Raketenschlag", ["text"] = "30 Meter Reichweite\nWirken in 3 sek.\nFügt 30 Feuerschaden in einem Radius von 3 Metern zu." }
entries[1943] = { ["name"] = "Blutung", ["text"] = "25 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der Schaden im Lauf der Zeit verursacht, erhöht durch Eure Angriffskraft. Hält pro Combopunkt länger an:\n1 Punkt: [( 231 + 2 * 1 + 0.025 * Angriffskraft * 1 ) * 0.5 * 8] Schaden im Verlauf von 8 Sek.\n2 Punkte: [( 231 + 2 * 1 * 2 + 0.04 * Angriffskraft * 1 ) * 0.5 * 12] Schaden im Verlauf von 12 Sek.\n3 Punkte: [( 231 + 2 * 1 * 3 + 0.05 * Angriffskraft * 1 ) * 0.5 * 16] Schaden im Verlauf von 16 Sek.\n4 Punkte: [( 231 + 2 * 1 * 4 + 0.056 * Angriffskraft * 1 ) * 0.5 * 20] Schaden im Verlauf von 20 Sek.\n5 Punkte: [( 231 + 2 * 1 * 5 + 0.062 * Angriffskraft * 1 ) * 0.5 * 24] Schaden im Verlauf von 24 Sek." }
entries[1949] = { ["name"] = "Höllenfeuer", ["text"] = "2% von Grundmana, plus 2% pro Sekunde\nKanalisiert (Wirken in 14 sek.)\nEntzündet den Bereich um den Zaubernden herum, wodurch er selbst alle 1 Sek. 1 Feuerschaden erleidet und allen Gegnern in der Nähe im gleichen Intervall 224 Feuerschaden zufügt. Hält 14 Sek. lang an.\n\nErzeugt 10 dämonischen Furor pro Sekunde und zusätzlich 3 dämonischen Furor pro Sekunde von Sekundärzielen." }
entries[1950] = { ["name"] = "Großer Schattenwichtel" }
entries[1953] = { ["name"] = "Blinzeln", ["text"] = "2% von Grundmana\nSofort 15 sek. Abklingzeit\nTeleportiert den Zaubernden 20 Meter [ Glyphe 'Momentum' : in die Richtung, in die er sich bewegt / nach vorn], es sei denn, etwas steht im Weg. Befreit den Zaubernden auch von Betäubungs- und Bewegungsunfähigkeitseffekten." }
entries[1966] = { ["name"] = "Finte", ["text"] = "20 Energie\nSofort\nFührt ein Ausweichmanöver durch, das 5 Sek. lang Euren [ Flüchtigkeit : gesamten erlittenen Schaden um 0% sowie Euren ]durch Flächeneffekte erlittenen Schaden um 50% verringert." }
entries[1978] = { ["name"] = "Schlangengift", ["text"] = "15 Fokus 40 Meter Reichweite\nSpontanzauber\nBenötigt Distanzwaffe\nVerursacht im Verlauf von 15 Sek. 16202 Naturschaden." }
