entries[2006] = { ["name"] = "Auferstehung", ["text"] = "4% von Grundmana 40 Meter Reichweite\nWirken in 10 sek.\nBringt einen toten Verbündeten mit 35% Gesundheit und Mana ins Leben zurück. Kann nicht während des Kampfes verwendet werden." }
