entries[2018] = { ["name"] = "Schmiedekunst", ["text"] = "Sofort\nErmöglicht einem Schmied, einfache Waffen und Rüstung mit einer maximalen potenziellen Fertigkeit von 75 herzustellen. Es werden Stein und Metall benötigt, die mit der Bergbaufertigkeit gefunden wurden." }
