entries[2062] = { ["name"] = "Totem des Erdelementars", ["text"] = "28.1% von Grundmana\nSofort 5 min Abklingzeit\nBeschwört ein Erdtotem mit 154755 Gesundheit zu Füßen des Zaubernden, das einen großen Erdelementar ruft, um den Zaubernden und seine Verbündeten zu beschützen. Hält 1 Min. lang an." }
