entries[2094] = { ["name"] = "Blenden", ["text"] = "15 Energie 15 Meter Reichweite\nSofort 2 min Abklingzeit\nBlendet das Ziel und lässt es bis zu 1 Min. lang desorientiert umherlaufen. Jeglicher erlittene Schaden wird den Effekt aufheben [ Glyphe 'Blenden' : Entfernt alle auf dem Ziel aktiven regelmäßigen Effekte, die 'Blenden' vorzeitig abbrechen würden ]. Bricht Verstohlenheit nicht ab." }
entries[2096] = { ["name"] = "Gedankensicht", ["text"] = "1% von Grundmana Unbegrenzte Reichweite\nKanalisiert (Wirken in 1 min)\nErmöglicht dem Zaubernden, 1 Min. lang durch die Augen des Ziels zu sehen. Funktioniert nicht, wenn sich das Ziel in einer anderen Instanz oder auf einem anderen Kontinent befindet." }
entries[2098] = { ["name"] = "Ausweiden", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der Schaden pro Combopunkt verursacht:\n1 Punkt: [ 333 + (5 + Angriffskraft * 0.18) * 1 ] bis [ 998 + (5 + Angriffskraft * 0.18) * 1 ] Schaden\n2 Punkte: [ 333 + ((10) + Angriffskraft * 0.36) * 1 ] bis [ 998 + ((10) + Angriffskraft * 0.36) * 1 ] Schaden\n3 Punkte: [ 333 + ((15) + Angriffskraft * 0.54) * 1 ] bis [ 998 + ((15) + Angriffskraft * 0.54) * 1 ] Schaden\n4 Punkte: [ 333 + ((20) + Angriffskraft * 0.72) * 1 ] bis [ 998 + ((20) + Angriffskraft * 0.72) * 1 ] Schaden\n5 Punkte: [ 333 + ((25) + Angriffskraft * 0.9) * 1 ] bis [ 998 + ((25) + Angriffskraft * 0.9) * 1 ] Schaden" }
entries[2108] = { ["name"] = "Lederverarbeitung", ["text"] = "Sofort\nErmöglicht einem Lederer die Herstellung von Lederrüstung mit einer maximalen potenziellen Fertigkeit von 75. Erfordert Lederfetzen und Bälge, die mit der Kürschnereifertigkeit gesammelt werden können." }
