entries[2120] = { ["name"] = "Flammenstoß", ["text"] = "6% von Grundmana 40 Meter Reichweite\nWirken in 2 sek. 12 sek. Abklingzeit\nLässt eine Feuersäule niedergehen, die alle Feinde im Gebiet verbrennt und ihnen zunächst 475 Feuerschaden und zusätzlich im Verlauf von 8 Sek. 4 Feuerschaden zufügt. [ Pyroschlag : Eine Flammenwelle breitet sich vom Ausgangspunkt aus und alle von dieser Welle getroffenen Feinde werden 3 Sek. lang um 50% verlangsamt ]" }
