entries[2637] = { ["name"] = "Winterschlaf", ["text"] = "6.5% von Grundmana 30 Meter Reichweite\nWirken in 1.5 sek.\nZwingt das feindliche Ziel bis zu 40 Sek. lang zu schlafen. Jeglicher Schaden führt dazu, dass das Ziel erwacht. Es kann immer nur jeweils ein Ziel in Winterschlaf versetzt werden. Wirkt nur bei Wildtieren und Drachkin." }
