entries[4096] = { ["name"] = "Raptorbalgharnisch", ["text"] = "Wirken in 3.5 sek.\nReagenzien:\nRaptorbalg (6), Schweres Leder (4), Feiner Faden (2)\nRaptorbalgharnisch\nWird beim Anlegen gebunden\nBrust Leder\n134 Rüstung\n+10 Ausdauer\nErhöht Eure Waffenkundewertung um + 7.\nHaltbarkeit 115 / 115\n28" }
