entries[4100] = { ["name"] = "Goblinlandmine", ["text"] = "5 Meter Reichweite\nSofort\nPlatziert die Goblinlandmine auf dem Boden. Sie explodiert, sobald eine feindliche Kreatur an ihr vorbeigeht, und fügt ihr 450 Feuerschaden zu. Die Mine ist 1 Min. lang aktiv." }
